static int stm32_rproc_mem_alloc ( struct rproc * rproc , struct rproc_mem_entry * mem ) { struct device * dev = rproc -> dev . parent ; void * va ; dev_dbg ( dev , "map memory: %pa+%x\n" , & mem -> dma , mem -> len ) ; if ( IS_ERR_OR_NULL ( va ) ) { dev_err ( dev , "Unable to map memory region: %pa+%x\n" , & mem -> dma , mem -> len ) ; return - ENOMEM ; } mem -> va = va ; return 0 ; } 